.card{position:relative;width:116px;height:158px;border:3px solid var(--ink);border-radius:12px;background:#fffdf3;padding:8px;box-shadow:5px 7px 0 #5d716557;cursor:pointer;transition:.16s;text-align:left}
.card:hover:not(:disabled){transform:translateY(-12px) rotate(-1deg)}
.card:disabled{opacity:.55;cursor:not-allowed}
.card.green{background:#dceab2}
.card.red{background:#ffd6bd}
.card.blue{background:#cce4df}
.card-cost{position:absolute;left:-9px;top:-9px;width:38px;height:38px;border:3px solid var(--ink);border-radius:50%;background:#73b8b6;display:grid;place-items:center;font-weight:900}
.card-title{height:28px;font-size:12px;text-align:center;font-weight:900;padding-top:5px}
.card-model{height:82px;border:2px solid var(--ink);border-radius:8px;background:linear-gradient(145deg,#87cfd0,#e9edaa);display:grid;place-items:center;font-size:38px}
.card-desc{font-size:10px;text-align:center;margin-top:7px;font-weight:700}
.card{width:92px;min-width:92px;height:128px}
.card-model{height:58px;font-size:28px}
.card-title{font-size:10px}
.card-desc{font-size:8px}
.end-turn{width:112px;height:112px;justify-self:end;border:4px solid var(--ink);border-radius:50%;background:var(--orange);box-shadow:5px 7px 0 #122b2c55;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer}
.end-turn:hover{transform:translateY(-3px)}
.end-turn small{font-size:10px;letter-spacing:2px}
.end-turn strong{font-size:17px}
.end-turn{width:68px;height:68px}
.end-turn strong{font-size:12px}
